test "every face's normal is a unit vector" {
    for (MODEL.faces) |fc| {
        const n = fc.n;
        const len2 = @as(i64, n[0]) * n[0] + @as(i64, n[1]) * n[1] + @as(i64, n[2]) * n[2];
        try std.testing.expect(@abs(len2 - 16384 * 16384) < 16384 * 8);
    }
}
